def deepseek_sin_saldo():
    """True si DeepSeek esta dormido por falta de saldo o cuota."""
    from cuerpo import cuotas
    dormido = cuotas._leer().get('dormidos', {}).get('deepseek')
    if not dormido:
        return False
    motivo = str(dormido.get('motivo', '')).lower()
    for senal in ('insufficient balance', 'insufficient_quota', 'payment required', '402'):
        if senal in motivo:
            return True
    return False

